const input = $input.first().json;
const ticket = input.body ?? input;

const ticketId = Number(ticket.ticketId);
if (!Number.isInteger(ticketId) || ticketId <= 0) {
  throw new Error('Payload invalido: falta un ticketId numerico.');
}

const normalize = (value) =>
  String(value ?? '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');

const text = `${normalize(ticket.title)} ${normalize(ticket.description)}`;
const has = (...needles) => needles.some((n) => text.includes(n));

let category;
if (has('sugerencia', 'feedback', 'me encantaria', 'me gustaria', 'estoy evaluando', 'consulta sobre', 'comparativa')) {
  category = 'other';
} else if (
  has('factura', 'facturacion', 'cobro', 'cargo', 'reembolso', 'suscripcion','ciclo de cobro', 'dar de baja', 'cancelar', 'plan pro', 'plan base', 'tarjeta', 'datos fiscales')
) {
  category = 'billing';
} else if (
  has('error', 'falla', 'fallo', 'crash', 'se cierra', 'se cae', 'no carga', 'no funciona','no recibo', 'notificacion', 'exportar', 'dashboard', 'pantalla', 'lento', 'bug', 'error-500', 'server-error', 'sesion', 'iniciar sesion', 'login')
) {
  category = 'technical';
} else if (
  has('cuenta', 'email', 'correo', 'contrasena', 'usuario', 'perfil', 'acceso', 'restablecer')
) {
  category = 'account';
} else {
  category = 'other';
}

let priority;
if (has('urgente', 'constantemente', 'cada pocos minutos', 'todo el tiempo', 'no puedo trabajar', 'todos los usuarios', 'caido', 'inaccesible', 'perdida de datos', 'no puedo')) {
  priority = 'urgent';
} else if (has('duplicado', 'error 500', 'error del servidor', 'no puedo acceder', 'fraude', 'cobro indebido')) {
  priority = 'high';
} else if (has('sugerencia', 'consulta', 'duda', 'me encantaria', 'como procedo', 'quisiera saber', 'me gustaria', 'solicito', 'estoy evaluando')) {
  priority = 'low';
} else {
  priority = 'medium';
}

const TAG_RULES = [
  ['factura', 'facturacion'], ['cobro', 'facturacion'], ['cargo', 'facturacion'], ['reembolso', 'reembolso'], ['duplicad', 'duplicado'], ['suscripcion', 'suscripcion'], ['dar de baja', 'cancelacion'], ['datos fiscales', 'datos-fiscales'], ['plan pro', 'planes'], ['plan base', 'planes'], ['tarjeta', 'pago'], ['android', 'android'], ['iphone', 'ios'], ['crash', 'crash'], ['se cierra', 'crash'], ['error 500', 'server-error'], ['exportar', 'export'],  ['pdf', 'pdf'], ['dashboard', 'dashboard'], ['no carga', 'no-carga'], ['bug', 'bug'], ['lento', 'rendimiento'], ['pantalla', 'ui'], ['notificacion', 'notificaciones'], ['server', 'server-error'], ['sesion', 'sesion'], ['iniciar sesion', 'auth'], ['contrasena', 'password'], ['email', 'email'], ['correo', 'email'], ['cuenta', 'cuenta'], ['perfil', 'perfil'], ['restablecer', 'recuperar'], ['usuario', 'usuario'], ['sugerencia', 'feedback'], ['planes', 'planes'], ['precios', 'planes'], ['modo oscuro', 'ux'], ['consulta', 'consulta'], ['modo claro', 'ux'], ['boton', 'ui'], ['color', 'ui'],
];

const tags = [];
for (const [needle, tag] of TAG_RULES) {
  if (text.includes(needle) && !tags.includes(tag)) tags.push(tag);
  if (tags.length === 4) break;
}
if (tags.length === 0) tags.push(category);

return [{ json: { ticketId, priority, category, tags } }];
